import 'dart:convert';
import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:share_plus/share_plus.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/pet.dart';import '../../../core/domain/care_entities.dart';import '../../../core/domain/extended_entities.dart';
class SitterHandoffScreen extends ConsumerStatefulWidget{const SitterHandoffScreen({super.key});@override ConsumerState<SitterHandoffScreen> createState()=>_SitterHandoffScreenState();}
class _SitterHandoffScreenState extends ConsumerState<SitterHandoffScreen>{bool profile=true,feeding=true,activity=true,reminders=true,contacts=true,records=false,careLogs=false,notes=false;@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider),pet=c.selectedPet;return Scaffold(appBar:AppBar(title:const Text('Pet-sitter handoff')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Choose exactly what to include. Review the preview before sharing.'),if(pet==null)const Text('Add a pet first.'),...[_Option('Pet name and profile',profile,(v)=>setState(()=>profile=v)),_Option('Feeding journal',feeding,(v)=>setState(()=>feeding=v)),_Option('Activity routine',activity,(v)=>setState(()=>activity=v)),_Option('Upcoming reminders',reminders,(v)=>setState(()=>reminders=v)),_Option('Vet and emergency contacts',contacts,(v)=>setState(()=>contacts=v)),_Option('Health records (sensitive)',records,(v)=>setState(()=>records=v)),_Option('Care timeline',careLogs,(v)=>setState(()=>careLogs=v)),_Option('Private notes (sensitive)',notes,(v)=>setState(()=>notes=v))],FilledButton(onPressed:pet==null?null:()async{final p=pet;final data=<String,dynamic>{'title':'PawPal care handoff','created_at':DateTime.now().toIso8601String()};if(profile)data['pet']={'name':p.name,'species':p.species,'breed':p.breed};if(feeding)data['feeding']=c.items('feeding_entries').map(FeedingEntry.fromMap).where((e)=>e.petId==p.id).map((e)=>{'food':e.food,'amount':e.amount,'unit':e.unit,'meal_type':e.mealType,'note':e.note}).toList();if(activity)data['activity']=c.items('activity_entries').map(ActivityEntry.fromMap).where((e)=>e.petId==p.id).map((e)=>{'type':e.type,'duration_minutes':e.durationMinutes,'note':e.note}).toList();if(reminders)data['reminders']=c.items('reminders').map(Reminder.fromMap).where((e)=>e.petId==p.id&&e.enabled&&!e.completed).map((e)=>{'title':e.title,'due_at':e.dueAt.toIso8601String(),'note':e.note}).toList();if(contacts)data['contacts']=c.items('contacts').map(ContactCard.fromMap).where((e)=>e.petId==null||e.petId==p.id).map((e)=>{'type':e.type,'name':e.name,'phone':e.phone,'address':e.address}).toList();if(records)data['health_records']=c.items('pet_records').map(PetRecord.fromMap).where((e)=>e.petId==p.id).map((e)=>{'type':e.type,'title':e.title,'event_date':e.eventDate.toIso8601String(),'follow_up_date':e.followUpDate?.toIso8601String(),'clinic':e.clinic,'notes':e.notes}).toList();if(careLogs)data['care_timeline']=c.items('care_logs').map(CareLog.fromMap).where((e)=>e.petId==p.id).map((e)=>{'type':e.type,'title':e.title,'at':e.at.toIso8601String(),'note':e.note}).toList();if(notes)data['owner_notes']=p.notes;final text=const JsonEncoder.withIndent('  ').convert(data);if(!context.mounted)return;final approved=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Review private handoff'),content:SizedBox(width:400,child:SingleChildScrollView(child:SelectableText(text))),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Share'))]));if(approved==true)await SharePlus.instance.share(ShareParams(text:text,subject:'${p.name} — care handoff'));},child:const Text('Preview and share'))]));}}
class _Option extends StatelessWidget{const _Option(this.title,this.value,this.changed);final String title;final bool value;final ValueChanged<bool> changed;@override Widget build(BuildContext context)=>SwitchListTile(value:value,title:Text(title),onChanged:changed);}
